// Sync window + config for the poller. Single source of truth: edit values HERE only.
const CONFIG = {
  // --- Simpro ---
  simproBaseUrl: 'https://spl.simprosuite.com/api/v1.0', // same host as the existing Get Simpro * nodes
  simproCompanyId: 4,        // Quotes + Jobs. From the pinned Job webhook event (reference.companyID = 4). CONFIRM with SPL.
  simproSharedCompanyId: 0,  // Customers, Contacts, Sites. Matches the /companies/0/ already used by Get Simpro Customer / Contact.
  // --- Window ---
  overlapMinutes: 2,          // re-read this far back from the last window end (clock skew / late commits). Upserts are idempotent.
  initialLookbackMinutes: 35, // used when there is no saved watermark (first run, or any manual test run)
  windowStartOverride: '',    // optional ISO date-time e.g. '2026-10-07T00:00:00Z' - forces the window start (backfill / recovery). Clear afterwards.
};

const state = $getWorkflowStaticData('global'); // only persists on production (trigger) runs, not manual test runs
const now = new Date();
let from;
let fromSource;

if (CONFIG.windowStartOverride) {
  from = new Date(CONFIG.windowStartOverride);
  if (isNaN(from.getTime())) {
    throw new Error('windowStartOverride is not a valid ISO date-time: ' + CONFIG.windowStartOverride);
  }
  fromSource = 'override';
} else if (state.lastWindowEnd) {
  from = new Date(new Date(state.lastWindowEnd).getTime() - CONFIG.overlapMinutes * 60000);
  fromSource = 'watermark';
} else {
  from = new Date(now.getTime() - CONFIG.initialLookbackMinutes * 60000);
  fromSource = 'initial lookback';
}
if (from.getTime() >= now.getTime()) {
  throw new Error('Sync window starts in the future (' + from.toISOString() + '). Check windowStartOverride and the saved watermark.');
}

return [{ json: {
  ...CONFIG,
  windowFrom: from.toISOString(),
  windowTo: now.toISOString(),
  ifModifiedSince: from.toUTCString(), // Simpro If-Modified-Since needs an HTTP-date in GMT
  fromSource,
} }];

// Turns the five Simpro "changed since" lists into ONE item per changed record, shaped exactly like
// the webhook payload the Record Sync workflow already understands:
//   { body: { name: 'Site', reference: { companyID, siteID } } }
const win = $('Build Sync Window').first().json;

const SOURCES = [
  { node: 'Fetch Changed Customers', event: 'Company customer', idKey: 'customerID', companyId: win.simproSharedCompanyId },
  { node: 'Fetch Changed Sites',     event: 'Site',             idKey: 'siteID',     companyId: win.simproSharedCompanyId },
  { node: 'Fetch Changed Contacts',  event: 'Contact',          idKey: 'contactID',  companyId: win.simproSharedCompanyId },
  { node: 'Fetch Changed Quotes',    event: 'Quote',            idKey: 'quoteID',    companyId: win.simproCompanyId },
  { node: 'Fetch Changed Jobs',      event: 'Job',              idKey: 'jobID',      companyId: win.simproCompanyId },
];

const records = [];
const counts = {};

for (const s of SOURCES) {
  const pages = $(s.node).all().map(i => i.json); // one item per page (fullResponse)
  const seen = new Set();
  let rows = 0;
  let reportedTotal = null;

  for (const page of pages) {
    if (page.statusCode === 304) continue; // Simpro: nothing modified since the window start
    if (page.statusCode !== 200) {
      throw new Error(s.node + ': Simpro returned HTTP ' + page.statusCode + ' - ' + JSON.stringify(page.body).slice(0, 300));
    }
    if (!Array.isArray(page.body)) {
      throw new Error(s.node + ': expected a JSON array from Simpro, got ' + typeof page.body);
    }
    if (reportedTotal === null && page.headers && page.headers['result-total'] !== undefined) {
      reportedTotal = Number(page.headers['result-total']);
    }
    for (const row of page.body) {
      if (row === null || typeof row !== 'object' || row.ID === undefined || row.ID === null) {
        throw new Error(s.node + ': a returned record has no ID - check the columns=ID query parameter.');
      }
      rows++;
      if (seen.has(row.ID)) continue;
      seen.add(row.ID);
      records.push({ json: {
        hasRecords: true,
        body: { name: s.event, reference: { companyID: s.companyId, [s.idKey]: row.ID } },
        meta: { source: 'poll', windowFrom: win.windowFrom, windowTo: win.windowTo },
      } });
    }
  }

  // The pagination cap stops silently - fail loudly instead of syncing a partial window.
  if (reportedTotal !== null && rows < reportedTotal) {
    throw new Error(s.node + ': read ' + rows + ' of ' + reportedTotal + ' changed records (page cap of 40 x 100 reached). '
      + 'Shorten the window (windowStartOverride) or raise Max Pages on that node.');
  }
  counts[s.event] = seen.size;
}

if (records.length === 0) {
  return [{ json: { hasRecords: false, windowFrom: win.windowFrom, windowTo: win.windowTo, counts } }];
}
return records;

// Collapse whatever the sub-workflow returned (0, 1 or many items) into exactly ONE result item,
// so the loop receives one clean result per record. Deliberately runOnceForAllItems.
const rec = $('Loop Over Records').first().json;
const ref = rec.body.reference;
const idKey = Object.keys(ref).find(k => k !== 'companyID');

// With onError = continueRegularOutput, a failed sub-execution comes back as an item carrying `error`.
const failure = $input.all().map(i => i.json).find(j => j && j.error);
let error = null;
if (failure) {
  const e = failure.error;
  error = typeof e === 'string' ? e : ((e && (e.message || e.description)) || JSON.stringify(e));
}

return [{ json: { ok: !failure, type: rec.body.name, id: ref[idKey], error } }];

// Runs ONCE per poll: when the loop is finished, or straight away when there was nothing to sync.
// Fails the run (-> error workflow) if any record failed; only advances the watermark on full success.
const win = $('Build Sync Window').first().json;
const expected = $('Build Record List').all().filter(i => i.json.hasRecords === true).length;
const results = $input.all().map(i => i.json).filter(j => j.ok !== undefined);

if (results.length !== expected) {
  throw new Error('Poll loop returned ' + results.length + ' result(s) for ' + expected
    + ' record(s) - NOT advancing the window. Check the Loop Over Records wiring.');
}

const failed = results.filter(r => r.ok === false);
if (failed.length > 0) {
  const lines = failed.slice(0, 20).map(f => '- ' + f.type + ' ' + f.id + ': ' + f.error);
  throw new Error(failed.length + ' of ' + results.length + ' record(s) failed for window '
    + win.windowFrom + ' to ' + win.windowTo + '. The window is NOT advanced, so the next run re-reads it '
    + '(upserts are idempotent).\n' + lines.join('\n'));
}

// Full success: advance the watermark. Only persists on production (trigger) runs.
const state = $getWorkflowStaticData('global');
state.lastWindowEnd = win.windowTo;

const byType = {};
for (const r of results) byType[r.type] = (byType[r.type] || 0) + 1;

return [{ json: {
  status: 'ok',
  recordsSynced: results.length,
  byType,
  windowFrom: win.windowFrom,
  windowTo: win.windowTo,
  windowStartedFrom: win.fromSource,
  watermarkSavedTo: win.windowTo,
} }];
